fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // Assuming all arrays have the same length
    let len = vals_1.len();
    avgs.clear();
    avgs.reserve(len);

    for i in 0..len {
        match (conds_1[i], conds_2[i]) {
            (true, true) => {
                // Both true: average of the two integers (integer division)
                avgs.push((vals_1[i] + vals_2[i]) / 2);
            }
            (true, false) => {
                // Only first is true: copy from vals_1
                avgs.push(vals_1[i]);
            }
            (false, true) => {
                // Only second is true: copy from vals_2
                avgs.push(vals_2[i]);
            }
            (false, false) => {
                // According to problem statement, this case won't occur
                // but if it does, let's just push zero (or panic)
                // panic!("At least one boolean must be true");
                avgs.push(0);
            }
        }
    }
}